    the SUT containing an a list of Temporal Entities 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Query Temporal Representation Of Entities with Response Status Code set to 200     and
        Query Temporal Representation Of Entities with Response Body containing a list of entities equal to '${2}' of type 'Vehicle' with response set to '${response.json()}'
}

